import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd();

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def verify(name, source, expect_rc):
    root = write_project(name, source)
    proc = subprocess.run(['cargo', 'run', '-q', '-p', 'fz', '--', 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == expect_rc, (name, proc.returncode, payload, proc.stderr)
    return payload

def messages(payload):
    return [item['message'] for item in payload['items']]

def find_message(payload, needle):
    return next(item for item in payload['items'] if needle in item['message'])

branch_relay = verify('branch_relay', '''
    fn produce() -> *mut u8 {
        let p = alloc(32)
        return p
    }
    fn relay(flag: i32) -> *mut u8 {
        if flag == 0 {
            return produce()
        }
        return produce()
    }
    fn main() -> i32 {
        let p = relay(0)
        free(p)
        return 0
    }
''', 0)
assert branch_relay['errors'] == 0, branch_relay
assert not any('memory lifecycle imbalance' in message for message in messages(branch_relay)), branch_relay
assert not any('potential resource escape' in message for message in messages(branch_relay)), branch_relay

if_expr_relay = verify('if_expr_relay', '''
    fn produce() -> *mut u8 {
        let p = alloc(32)
        return p
    }
    fn relay(flag: i32) -> *mut u8 {
        return if flag == 0 { produce() } else { produce() }
    }
    fn main() -> i32 {
        let p = relay(0)
        free(p)
        return 0
    }
''', 0)
assert if_expr_relay['errors'] == 0, if_expr_relay
assert not any('memory lifecycle imbalance' in message for message in messages(if_expr_relay)), if_expr_relay

handle_wrapper = verify('handle_wrapper', '''
    use core.thread;
    fn worker() -> i32 {
        return 7
    }
    fn start() -> TaskHandle {
        return spawn(worker)
    }
    fn main() -> i32 {
        let handle = start()
        return join(handle)
    }
''', 0)
assert handle_wrapper['errors'] == 0, handle_wrapper
assert not any('memory lifecycle imbalance' in message for message in messages(handle_wrapper)), handle_wrapper
assert not any('potential resource escape' in message for message in messages(handle_wrapper)), handle_wrapper

imbalance_fail = verify('imbalance_fail', '''
    fn main() -> i32 {
        let left = alloc(32)
        let right = alloc(64)
        free(left)
        return 0
    }
''', 1)
imbalance_diag = find_message(imbalance_fail, 'memory lifecycle imbalance: alloc sites=2 free sites=1 returned-owned sites=0')
assert 'return the owned value explicitly on every allocating path' in (imbalance_diag.get('help') or ''), imbalance_diag

print('compiler-memory-transfer-relays-ok')

